} from "../../lib/animation";

export type ToggleGroupRootProps = Omit<
  ComponentProps<typeof ToggleGroupPrimitive.Root>,
  "type" | "value" | "defaultValue" | "onValueChange"
> & {
  className?: string;
  children?: ReactNode;
  /**
   * When `"single"`, only one item can be pressed.
   * When `"multiple"`, many items can be pressed.
   */
  type?: "single" | "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (groupValue: string[]) => void;
};

export type ToggleGroupItemProps = {
  "aria-label"?: string;
  children?: ReactNode;
  className?: string;
  disabled?: boolean;
  value: string;
};

/** Convenience alias for AutoTypeTable */
export type ToggleGroupProps = ToggleGroupRootProps;

type RadixRootProps = ComponentProps<typeof ToggleGroupPrimitive.Root>;

/**
 * SmoothUI Toggle Group — Radix twin.
 * Same public props as the Base UI twin (`type` + string[] value).
 *
 * Items are styled directly on `ToggleGroup.Item`, which renders a Motion
 * button through `asChild` so `role`, `aria-pressed` / `data-state`, and
 * keyboard roving focus stay on the focusable control while it gets the same
 * press feedback as the Base twin.
 */
const ToggleGroupRoot = ({
  className,
  children,
  type = "single",
  value,
  defaultValue,
  onValueChange,
  ...props
}: ToggleGroupRootProps) => {
  if (type === "multiple") {
    return (
      <ToggleGroupPrimitive.Root
        className={cn(
          "inline-flex items-center justify-center gap-0.5 rounded-lg bg-foreground/10 p-1",
          "data-[orientation=vertical]:flex-col",
          className
        )}
        data-slot="toggle-group"
        defaultValue={defaultValue as string[] | undefined}
        onValueChange={(next) => {
          (onValueChange as ((groupValue: string[]) => void) | undefined)?.(
            next
          );
        }}
        type="multiple"
        value={value as string[] | undefined}
        {...(props as Omit<
          RadixRootProps,
          "type" | "value" | "defaultValue" | "onValueChange"
        >)}
      >
        {children}
      </ToggleGroupPrimitive.Root>
    );
  }

  const singleValue = value?.[0];
  const singleDefault = defaultValue?.[0];

  return (
    <ToggleGroupPrimitive.Root
      className={cn(
        "inline-flex items-center justify-center gap-0.5 rounded-lg bg-foreground/10 p-1",
        "data-[orientation=vertical]:flex-col",
        className
      )}
      data-slot="toggle-group"
      defaultValue={singleDefault}
      onValueChange={(next) => {
        (onValueChange as ((groupValue: string[]) => void) | undefined)?.(
          next ? [next] : []
        );
      }}
      type="single"
      value={singleValue}
      {...(props as Omit<
        RadixRootProps,
        "type" | "value" | "defaultValue" | "onValueChange"
      >)}
    >
      {children}
    </ToggleGroupPrimitive.Root>
  );
};

