  <div className="flex items-center gap-2">
    <a href={tweet.user.url} rel="noreferrer" target="_blank">
      <img
        alt={tweet.user.screen_name}
        className={cn("size-10 object-cover object-center", avatarRounded)}
        draggable={false}
        height={40}
        loading="eager"
        src={tweet.user.profile_image_url_https}
        title={`Profile picture of ${tweet.user.name}`}
        width={40}
      />
    </a>
    <div>
      <p className="font-semibold text-foreground text-sm tracking-tighter 2xl:text-base">
        {tweet.user.name}
      </p>
      <p className="text-foreground/60 text-xs 2xl:text-sm">
        @{truncate(tweet.user.screen_name, 16)}
      </p>
    </div>
  </div>
);

export const TweetBody = ({ tweet }: { tweet: EnrichedTweet }) => (
  <blockquote className="flex-1">
    <p className="text-balance text-foreground text-sm tracking-tight 2xl:text-base">
      {tweet.entities.map((entity, idx) => {
        switch (entity.type) {
          case "url":
          case "symbol":
          case "hashtag":
          case "mention":
            return (
              <a
                className="ease text-foreground transition-colors duration-200 hover:text-foreground/80"
                href={entity.href}
                key={`${entity.type}-${idx}-${entity.text.slice(0, 10)}`}
                rel="noopener noreferrer"
                target="_blank"
              >
                <span>{entity.text}</span>
              </a>
            );
          case "text":
            return (
              <span
                className="text-foreground"
                // biome-ignore lint/suspicious/noArrayIndexKey: Text entities from tweet API have no unique IDs
                key={`text-${idx}`}
              >
                {entity.text}
              </span>
            );
          default:
            return null;
        }
      })}
    </p>
  </blockquote>
);

export const TweetMedia = ({ tweet }: { tweet: EnrichedTweet }) => {
  const hasVideo =
    tweet.video &&
    Array.isArray(tweet.video.variants) &&
    tweet.video.variants.length > 0;
  const hasPhotos = tweet.photos && tweet.photos.length > 0;
  const hasCardThumbnail =
    // @ts-expect-error package doesn't have type definitions
    tweet?.card?.binding_values?.thumbnail_image_large?.image_value.url;

  if (!(hasVideo || hasPhotos || hasCardThumbnail)) {
    return null;
  }

  return (
    <div className="flex w-full flex-col gap-2">
      {hasVideo && tweet.video ? (
        <video
          autoPlay
          className="w-full rounded-xl border shadow-sm"
          loop
          muted
          playsInline
          poster={tweet.video.poster}
        >
          <source src={tweet.video.variants[0].src} type="video/mp4" />
          Your browser does not support the video tag.
        </video>
      ) : null}
      {hasPhotos && tweet.photos
        ? (() => {
            const { photos } = tweet;
            return (
              <div className="relative grid w-full gap-2">
                {photos.length === 1 && (
                  <img
                    alt={tweet.text}
                    className="w-full rounded-xl border object-cover shadow-sm"
                    draggable={false}
                    height={photos[0].height}
                    key={photos[0].url}
                    src={photos[0].url}
                    title={`Photo by ${tweet.user.name}`}
                    width={photos[0].width}
                  />
                )}
                {photos.length === 2 && (
                  <div className="grid grid-cols-2 gap-2">
                    {photos.map((photo) => (
                      <img
                        alt={tweet.text}
                        className="w-full rounded-xl border object-cover shadow-sm"
                        draggable={false}
                        height={photo.height}
                        key={photo.url}
                        src={photo.url}
                        title={`Photo by ${tweet.user.name}`}
                        width={photo.width}
                      />
                    ))}
                  </div>
                )}
                {photos.length >= 3 && (
                  <div className="grid grid-cols-2 gap-2">
                    {photos.slice(0, 4).map((photo, index) => (
                      <img
                        alt={tweet.text}
                        className={cn(
                          "w-full rounded-xl border object-cover shadow-sm",
                          index === 0 && photos.length > 3 && "row-span-2"
                        )}
                        draggable={false}
                        height={photo.height}
                        key={photo.url}
                        src={photo.url}
                        title={`Photo by ${tweet.user.name}`}
                        width={photo.width}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })()
        : null}
      {!(hasVideo || hasPhotos) && hasCardThumbnail && (
        <img
          alt={tweet.text}
          className="w-full rounded-xl border object-cover shadow-sm"
          draggable={false}
          src={
            // @ts-expect-error package doesn't have type definitions
            tweet.card.binding_values.thumbnail_image_large.image_value.url
          }
        />
      )}
    </div>
  );
};

const entityList = <T,>(value: T[] | undefined): T[] =>
  Array.isArray(value) ? value : [];

// react-tweet's enrichTweet walks hashtags, mentions, urls, and symbols
// with for...of, including on quoted_tweet. The syndication API omits
// those arrays (entities can be {}), which throws "entities is not iterable".
const iterableEntities = (
  entities: Tweet["entities"] | undefined
): Tweet["entities"] => ({
  hashtags: entityList(entities?.hashtags),
  symbols: entityList(entities?.symbols),
  urls: entityList(entities?.urls),
  user_mentions: entityList(entities?.user_mentions),
  ...(Array.isArray(entities?.media) ? { media: entities.media } : {}),
});

const withIterableEntities = (tweet: Tweet): Tweet => ({
  ...tweet,
  entities: iterableEntities(tweet.entities),
  ...(tweet.quoted_tweet
    ? {
        quoted_tweet: {
          ...tweet.quoted_tweet,
          entities: iterableEntities(tweet.quoted_tweet.entities),
        },
      }
    : {}),
});

export const SmoothTweet = ({
  tweet,
  className,
  userInfoPosition = "bottom",
  avatarRounded = "rounded",
  ...props
}: {
  tweet: Tweet;
  className?: string;
  userInfoPosition?: "top" | "bottom";
  avatarRounded?: string;
}) => {
  const enrichedTweet = enrichTweet(withIterableEntities(tweet));
  const userInfo = (
    <TweetHeader avatarRounded={avatarRounded} tweet={enrichedTweet} />
  );
  const content = (
    <div className="flex w-full flex-col gap-4">
      <TweetMedia tweet={enrichedTweet} />
      {userInfoPosition === "bottom" && userInfo}
    </div>
  );

  return (
    <article
      className={cn(
        "group !p-6 relative flex flex-col items-start justify-between gap-6 overflow-hidden rounded-xl border bg-background lg:gap-8",
        className
      )}
      data-tweet
      {...props}
    >
      {userInfoPosition === "top" && userInfo}
      <TweetBody tweet={enrichedTweet} />
      {content}
      <button
        aria-label="Open tweet in new tab"
        className="absolute right-6 bottom-6 z-10 flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border bg-primary text-foreground opacity-0 backdrop-blur-sm transition-all duration-200 ease-out group-hover:opacity-100 motion-safe:hover:scale-110"
        onClick={() =>
          window.open(enrichedTweet.url, "_blank", "noopener,noreferrer")
        }
        type="button"
      >
        <ExternalLink className="h-4 w-4" />
      </button>
    </article>
  );
};

/**
 * TweetCard (Server Side Only)
 */
export type TweetCardProps = TweetProps & {
  className?: string;
  userInfoPosition?: "top" | "bottom";
  avatarRounded?: string;
};

export const TweetCard = async ({
  id,
  components,
  fallback = <TweetSkeleton />,
  onError,
  ...props
}: TweetCardProps) => {
  const tweet = id
    ? await getTweet(id).catch((err) => {
        if (onError) {
          onError(err);
        } else {
          console.error(err);
        }
      })
    : undefined;

  if (!tweet) {
    const NotFound = components?.TweetNotFound || TweetNotFound;
    return <NotFound {...props} />;
  }

  return (
    <Suspense fallback={fallback}>
      <SmoothTweet tweet={tweet} {...props} />
    </Suspense>
  );
};

